299	template <pipe_t SrcPipe, pipe_t DstPipe>
300	class EventIdCounter {
301	public:
302	    PTO_INTERNAL static event_t GetNextId()
303	    {
304	        event_t id = NextId();
305	#if defined(__CPU_SIM) || defined(__COSTMODEL)
306	        PTO_CPU_ASSERT(
307	            !(OccupiedMask() & (1u << static_cast<uint8_t>(id))), "Event ID still occupied - likely missing Wait()");
308	        OccupiedMask() |= (1u << static_cast<uint8_t>(id));
309	#endif
310	        NextId() = (event_t)(((uint8_t)NextId() + 1) % EVENT_ID_MAX);
311	        return id;
312	    }
313	    PTO_INTERNAL static void Reset()
314	    {
315	        NextId() = EVENT_ID0;
316	#if defined(__CPU_SIM) || defined(__COSTMODEL)
317	        OccupiedMask() = 0;
318	#endif
319	    }
320	    PTO_INTERNAL static event_t PeekNextId() { return NextId(); }
321	#if defined(__CPU_SIM) || defined(__COSTMODEL)
322	    PTO_INTERNAL static void MarkFree(event_t id) { OccupiedMask() &= ~(1u << static_cast<uint8_t>(id)); }
323	#endif
324	
325	private:
326	    static event_t& NextId()
327	    {
328	        static event_t id = EVENT_ID0;
329	        return id;
330	    }
331	#if defined(__CPU_SIM) || defined(__COSTMODEL)
332	    static uint8_t& OccupiedMask()
333	    {
334	        static uint8_t mask = 0;
335	        return mask;
336	    }
337	#endif
338	};
