346	template <pipe_t SrcPipe, pipe_t DstPipe>
347	PTO_INTERNAL void PtoSetWaitFlag(event_t SetEventId = EVENT_ID0, event_t WaitEventId = EVENT_ID0)
348	{
349	#ifndef __PTO_AUTO__
350	#ifdef PTO_FLAG_TEST
351	    CceEventIdType token = __pto_set_flag(SrcPipe, DstPipe);
352	    __pto_wait_flag(SrcPipe, DstPipe, token);
353	#else
354	    set_flag(SrcPipe, DstPipe, SetEventId);
355	    wait_flag(SrcPipe, DstPipe, WaitEventId);
356	#endif
357	#endif
358	}
359	struct EventBaseTag {};
360	
361	template <typename T>
362	struct is_event : std::is_base_of<EventBaseTag, T> {};
363	
364	template <typename... Ts>
365	inline constexpr bool all_events_v = (is_event<Ts>::value && ...);
366	
367	// CRTP base class for platform-specific Event implementations.
368	// Derived must provide:
369	//   template <Op op> static constexpr pipe_t GetPipeByOp()
370	//   static constexpr bool IsCrossCore
371	//   template <uint8_t CrossCoreId> PTO_INTERNAL Derived& WaitImpl()
372	//   template <uint8_t CrossCoreId> PTO_INTERNAL Derived& InitImpl()
373	//   PTO_INTERNAL Derived& InitAddrImpl(uint64_t fftsAddr)
374	template <typename Derived, Op SrcOp, Op DstOp, bool AutoToken = true, event_t EventID = EVENT_ID0>
375	struct EventBase : EventBaseTag {
376	#ifndef __PTO_AUTO__
377	    static constexpr Op srcOp = SrcOp;
378	    static constexpr Op dstOp = DstOp;
379	    static constexpr pipe_t srcPipe = Derived::template GetPipeByOp<SrcOp>();
380	    static constexpr pipe_t dstPipe = Derived::template GetPipeByOp<DstOp>();
381	    static constexpr bool isSamePipe = (srcPipe == dstPipe);
382	
383	#ifdef PTO_FLAG_TEST
384	    CceEventIdType token = {};
385	#else
386	    const event_t token = AutoToken ? EventIdCounter<srcPipe, dstPipe>::GetNextId() : EventID;
387	#endif
388	#endif
389	
390	    PTO_INTERNAL Derived& InitAddr(uint64_t fftsAddr) { return self().InitAddrImpl(fftsAddr); }
391	
392	    template <uint8_t CrossCoreId = 0xff>
393	    PTO_INTERNAL Derived& Wait()
394	    {
395	#ifndef __PTO_AUTO__
396	        return self().template WaitImpl<CrossCoreId>();
397	#else
398	        return self();
399	#endif
400	    }
401	
402	    template <uint8_t CrossCoreId = 0xff>
403	    PTO_INTERNAL Derived& Init()
404	    {
405	#ifndef __PTO_AUTO__
406	        return self().template InitImpl<CrossCoreId>();
407	#else
408	        return self();
409	#endif
410	    }
411	
412	    template <uint8_t CrossCoreId = 0xff>
413	    PTO_INTERNAL Derived& Record()
414	    {
415	        return Init<CrossCoreId>();
416	    }
417	
418	    PTO_INTERNAL EventBase() = default;
419	    PTO_INTERNAL EventBase(RecordEvent) { Init(); }
420	
421	    PTO_INTERNAL Derived& operator=(RecordEvent) { return Init(); }
422	
423	private:
424	    PTO_INTERNAL Derived& self() { return *static_cast<Derived*>(this); }
425	};
