476	template <typename TileData>
477	PTO_INTERNAL constexpr auto GetPadValue()
478	{
479	    using DType = typename TileData::DType;
480	    constexpr PadValue PadVal = TileData::PadVal;
481	    // Handle custom pad values (works on both CPU and NPU)
482	    if constexpr (isCustomPadValue(PadVal)) {
483	        constexpr uint32_t bits = getCustomPadBits(PadVal);
484	        if constexpr (std::is_same_v<DType, float>) {
485	            return bits; // float uses raw bits directly
486	        } else if constexpr (sizeof(DType) == 2) {
487	            // fp16 and bf16 both use lower 16 bits
488	            // (PadValueCustom(half) and PadValueCustom(bfloat16_t) store native bits)
489	            return static_cast<uint32_t>(bits & 0xFFFF);
490	        } else if constexpr (sizeof(DType) == 1) {
491	            return static_cast<uint32_t>(bits & 0xFF);
492	        } else {
493	            return bits;
494	        }
495	    } else {
496	        return PadValueMap<DType, PadVal>::value;
497	    }
498	}
