502	{
503	    if constexpr (TileData::isRowMajor && (TileData::SFractal == SLayout::NoneBox)) {
504	        return TileLayoutCustom::ND;
505	    } else if constexpr (!TileData::isRowMajor && (TileData::SFractal == SLayout::NoneBox)) {
506	        return TileLayoutCustom::DN;
507	    } else if constexpr (
508	        !TileData::isRowMajor && (TileData::SFractal == SLayout::RowMajor) && TileData::SFractalSize == 512) {
509	        return TileLayoutCustom::NZ;
510	    } else if constexpr (
511	        TileData::isRowMajor && (TileData::SFractal == SLayout::ColMajor) && TileData::SFractalSize == 512) {
512	        return TileLayoutCustom::ZN;
513	    } else if constexpr (
514	        TileData::isRowMajor && (TileData::SFractal == SLayout::RowMajor) && TileData::SFractalSize == 512) {
515	        return TileLayoutCustom::ZZ;
516	    } else {
517	        return TileLayoutCustom::NONE;
