361	template <typename KernelFn>
362	inline void LaunchKernelMultiCore(const KernelLaunchOptions& options, aclrtStream stream, KernelFn&& kernel)
363	{
364	    (void)stream;
365	    EnsureRuntimeInitialized();
366	
367	    const uint32_t subblocks_per_block = std::max<uint32_t>(1, options.subblocks_per_block);
368	    const uint32_t active_blocks =
369	        options.explicit_block_count != 0 ?
370	            options.explicit_block_count :
371	            ResolveActiveCoreCount(options.requested_cores, options.total_work_items, options.work_quantum);
372	    const uint32_t active_cores = active_blocks * subblocks_per_block;
373	    const bool trace_enabled = IsTraceEnabled() && options.write_trace_files;
374	    const std::filesystem::path trace_dir =
375	        trace_enabled ? CreateKernelTraceDir(options.kernel_name) : std::filesystem::path{};
376	
377	    std::vector<std::thread> workers;
378	    workers.reserve(active_cores);
379	    std::vector<std::string> trace_chunks(active_cores);
380	    std::exception_ptr first_error;
381	    std::mutex error_mutex;
382	
383	    for (uint32_t core_id = 0; core_id < active_cores; ++core_id) {
384	        workers.emplace_back([&, core_id]() {
385	            try {
386	                const uint32_t block_idx = core_id / subblocks_per_block;
387	                const uint32_t subblock_id = core_id % subblocks_per_block;
388	                ResetInstructionTrace();
389	                reset_execution_context();
390	                set_execution_context(block_idx, subblock_id, subblocks_per_block);
391	                kernel();
392	                if (trace_enabled) {
393	                    std::ostringstream out;
394	                    DumpInstructionTraceJson(out);
395	                    trace_chunks[core_id] = out.str();
396	                }
397	                reset_execution_context();
398	            } catch (...) {
399	                std::scoped_lock lock(error_mutex);
400	                if (first_error == nullptr) {
401	                    first_error = std::current_exception();
402	                }
403	            }
404	        });
405	    }
406	
407	    for (auto& worker : workers) {
408	        worker.join();
409	    }
410	
411	    if (first_error != nullptr) {
412	        std::rethrow_exception(first_error);
413	    }
414	
415	    if (trace_enabled) {
416	        std::ofstream combined(trace_dir / "trace.jsonl", std::ios::trunc);
417	        for (const auto& chunk : trace_chunks) {
418	            combined << chunk;
419	        }
420	    }
421	}
